const EDGE_OUT_0_PROJECT_SQL = `SELECT ?1 AS "item"`;
const EDGE_OUT_0_WRITE_SQL = `INSERT INTO "out" ("item") VALUES (?)`;
const EDGE_OUT_0_HEAD_COLUMNS: readonly string[] = ["item"];

const EDGE_OUT_1_PROJECT_SQL = `SELECT ?1 AS "item"`;
